using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SlowCoffee.Infrastructure.Data;
namespace SlowCoffee.Web.Controllers; public class HomeController(AppDbContext db):Controller { public async Task<IActionResult> Index(){ViewBag.TotalProdutos=await db.Produtos.CountAsync(x=>x.Ativo);ViewBag.TotalClientes=await db.Clientes.CountAsync(x=>x.Ativo);ViewBag.TotalPedidos=await db.Pedidos.CountAsync();ViewBag.Faturamento=await db.Pedidos.Where(x=>x.Status!=SlowCoffee.Domain.Entities.StatusPedido.Cancelado).SumAsync(x=>(decimal?)x.ValorTotal)??0;return View();} public IActionResult Error()=>View(); }
